import dotenv from "dotenv";
import cookieParser from "cookie-parser";
import { captureSentryException, flushSentry, setupSentryExpress } from "./instrument";

dotenv.config();

import { contactRouter } from "./api/contact/contact.router";
import { authRouter } from "./api/auth/auth.router";
import { dashboardRouter } from "./api/dashboard/dashboard.router";
import { paymentsRouter } from "./api/payments/payments.router";
import { shopifyRouter } from "./api/shopify/shopify.router";
import { shopifyDashboardRouter } from "./api/shopify-dashboard/shopifyDashboard.router";
import { merchantRouter } from "./api/olyx/merchant.router";
import { webhooksRouter } from "./api/webhooks/webhooks.router";
import { gdprRouter } from "./api/webhooks/gdpr.router";
import { whatsappRouter } from "./api/whatsapp/whatsapp.router";
import { widgetRouter } from "./api/widget/widget.router";
import { storesRouter } from "./api/stores/stores.router";

const app = express();

app.use(cors({
  origin: process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000",
  credentials: true,
}));
// Preserve raw body for Shopify + Meta webhook HMAC verification.
// Re-serializing JSON.parse'd bodies changes whitespace/key order and breaks HMAC.
app.use(
  express.json({
    verify: (req, _res, buf) => {
      (req as express.Request & { rawBody?: Buffer }).rawBody = buf;
    },
  })
);
app.use(cookieParser());

const PORT = process.env.PORT || 5000;

// Health check & root endpoints for Render deployment verification & pings
app.get("/", (_req, res) => {
  res.status(200).json({ status: "ok", service: "Flowqen Backend API" });
});
app.get("/health", (_req, res) => {
  res.status(200).json({ status: "ok" });
});
app.get("/api/health", (_req, res) => {
  res.status(200).json({ status: "ok" });
});

// Sentry onboarding snippet — GET this once, then delete the route.
app.get("/debug-sentry", function mainHandler(_req, _res) {
  throw new Error("My first Sentry error!");
});


import { instagramRouter } from "./api/instagram/instagram.router";

import { connect } from "./infrastructure/db/Db";
import { ensureIndexes } from "./infrastructure/db/mongo/ensureIndexes";
import { shutdownTelemetry } from "./infrastructure/observability/LangfuseTelemetry";

// Mount API Routers
app.use("/api/contact", contactRouter);
app.use("/api/auth", authRouter);
app.use("/api/stores", storesRouter);
app.use("/api/dashboard", dashboardRouter);
app.use("/api/payments", paymentsRouter);
app.use("/api/shopify", shopifyRouter);
app.use("/api/shopify-dashboard", shopifyDashboardRouter);
app.use("/api/merchant", merchantRouter);
app.use("/api/webhooks", webhooksRouter);
app.use("/api/webhooks/gdpr", gdprRouter);
app.use("/api/whatsapp", whatsappRouter);
app.use("/api/instagram", instagramRouter);
app.use("/api/widget", widgetRouter);

setupSentryExpress(app);

// Connect to MongoDB and sync indexes (replaces `prisma generate` + `prisma db push`),
// then open the HTTP port. Fail fast if DATABASE_URL is wrong.
async function start(): Promise<void> {
  await connect();
  await ensureIndexes();
  app.listen(Number(PORT), "0.0.0.0", () => {
    console.log(`🚀 Flowqen Backend Express Server running on port ${PORT}`);
  });
}

start().catch((error) => {
  console.error("Failed to start backend:", error);
  captureSentryException(error);
  void flushSentry().finally(() => process.exit(1));
});

// Render sends SIGTERM on deploys/restarts — flush Langfuse + Sentry first.
for (const signal of ["SIGTERM", "SIGINT"] as const) {
  process.on(signal, () => {
    void Promise.all([shutdownTelemetry(), flushSentry()]).finally(() => process.exit(0));
  });
}

# AI agent — how a turn works

Agent is the store’s sales associate. One customer message goes through a **loop**, not a single LLM call: retrieve knowledge, maybe call tools, then reply.

Product name in the UI: **Agent**. Runtime code: `backend/src/infrastructure/agent/`.

---

## One message, end to end

```
Customer (WhatsApp / Instagram / widget)
        │
        ▼
Channel router  →  HandleInboundMessage
        │
        ├─ batch (WhatsApp / IG)  conversationGraph.invoke
        │     session → gates → escalate → pause (human-ask) → finish
        │     else guard → route → retrieve → agent ⇄ tools → verify → finish
        ├─ stream (widget / sandbox)  conversationGraph.stream (+ FunctionCallTextFilter)
        ├─ human-ask interrupt holds the turn; PATCH OPEN → Command({ resume })
        ├─ ContextBuilder         find/create chat + last messages
        ├─ TurnSetup              intent, mode, Skills, knowledge, prompt, allowed tools
        ├─ SafetyGate             block jailbreaks / abuse
        ├─ Credits / daily cap     no AI call if store is out of credits or over maxMessagesPerDay
        ├─ IntentRouter        regex intent (policy before cancel/return)
        ├─ ModeRouter          shopping / order_support / returns / … → tool subset
        ├─ loadSkillPrompt     ACTIVE Skill text for this mode, plus any Skill that owns this intent
        ├─ RetrievalPipeline   RAG chunks from this store’s knowledge
        ├─ PromptComposer      system prompt = identity + grounding + RAG + Skill instructions
        ├─ ToolRegistry        enabledTools, then only tools this store can run
        │                      (commerce if Shopify/Woo connected; own_data always)
        │
        ▼
LLM (OpenAI / Groq / … via AIClientFactory)
        │
        ├─ may call tools (lookup_orders_by_customer, get_order_details, …)
        │     ToolExecutor → Shopify GraphQL / Prisma
        │     result snippet goes back to the model
        │
        ├─ BudgetManager       stop at 5 tools / 4 iterations / 12s
        │
        ▼
Reply + save conversation  (persistTurn upserts MissedQuestion if isMissed; escalate_to_human may create a Lead)
```

Streaming uses the same graph; `FunctionCallTextFilter` strips leaked `<function>` XML before tokens go to the widget.

## Where a Skill fits

A Skill is not its own LangGraph node. The `route` node only labels the message. The `retrieve` node calls `TurnSetup`, and that loads the Skill text before the model runs.

```
route        what kind of request is this?
retrieve     knowledge + matching Skill instructions + allowed tools
agent        model follows those instructions and may call a tool
```

`loadSkillPrompt` selects ACTIVE Skills in two ways:

1. The mode matches the built-in Skill group. A returns conversation gets the returns Skill.
2. The Skill owns this message’s intent key. This is how a merchant-created Skill is included.

The selected text is appended to the system prompt. It tells the model how to handle the request. It does not add tools by itself.

A short follow-up (“check”, “and the third one?”) does **not** carry intent in that line. `route` + `TurnSetup` read the last messages so we still load `order_support` tools and the Look up orders skill, and we reuse an email or phone already in this chat. See [order-lookup-context.md](./order-lookup-context.md). Return and cancel journeys are the only saved *step* sequences.

---



## Knowledge vs tools

These are **different memories**. Mixing them is the usual newcomer bug.


|         | Knowledge (RAG)                            | Tools                          |
| ------- | ------------------------------------------ | ------------------------------ |
| What    | PDFs, URLs, Q&A the merchant uploaded      | Live Shopify / DB actions      |
| When    | Batch: skip on smalltalk. Otherwise stuffed into the system prompt | Only if the model calls a tool |
| Example | “What’s your return window?”               | “Where is order #1042?”        |
| Stale?  | Until they re-ingest                       | Fresh from Shopify Admin       |


Grounding rule (PromptComposer): answer from retrieved knowledge **or** a tool result. Never invent order status, stock, or prices.

---



## Intent vs mode

Two regex classifiers. Easy to mix up.


|                     | `IntentRouter`                                                    | `ModeRouter`                                                               |
| ------------------- | ----------------------------------------------------------------- | -------------------------------------------------------------------------- |
| Asks                | What is this message *about*?                                     | Which *tools* may this turn see?                                           |
| Output              | `static_question`, `order_status`, `action`, `lead_or_handoff`, … | `shopping`, `order_support`, `returns`, `policy`, `complaint`, `smalltalk` |
| Used for            | Traces, dashboard, `requiresHuman` (only `lead_or_handoff`)       | `TurnSetup` `filterByNames(MODE_TOOLS[mode])`                              |
| Default if no match | `static_question`                                                 | `shopping` (so “red hoodie” still gets catalog tools)                      |


`TurnSetup` runs intent first, then `classifyMode(message, intent)`. Mode may use intent as a hint; **only mode changes the tool list.** Cancel/return are tools in `order_support` / `returns`, not an automatic human handoff.

Policy regex is in **both** files on purpose: “return policy” must stay `policy` / `static_question`, never a return write.

---



